<!--
 * 任务连接器（列表页）
 *
 * @path apps\cronjob-web\src\views\connector\index.vue
 * @author ydsz-team
 * @since 1.0.0
-->
<script lang="ts" setup>
/**
 * 任务连接器（列表页）
 * <p>消费后端契约 ConnectorController（src/api/connector.ts，auto-generated by bash/gen-contract.py）：
 * types() 展示支持的连接器类型；录入连接参数后 listRemoteTasks() 展示远程任务列表；
 * 工具按钮：测试连接（connector-form.vue 弹窗）、导入 importTasks()、导出 exportTasks()。
 *
 * @author ydsz-team
 * @since 1.0.0
 */
import type { VxeGridProps } from '@ydsz/plugins/vxe-table';

import { Page, useYDSZModal } from '@ydsz/common-ui';

import { ElButton, ElForm, ElFormItem, ElInput, ElMessage, ElTag } from 'element-plus';
import { onMounted, reactive, ref } from 'vue';
import { useI18n } from 'vue-i18n';

import { useYDSZVxeGrid } from '#/adapter/vxe-table';
import { exportTasks, importTasks, listRemoteTasks, types } from '#/api/connector';
import type { ConnectorConfigPostDTO, ConnectorTaskInfo } from '#/api/models';

import ConnectorForm from './connector-form.vue';

defineOptions({ name: 'ConnectorManagement' });
const { t } = useI18n();

/** 支持的连接器类型（types() 返回） */
const connectorTypes = ref<string[]>([]);

/** 页面级连接参数（用于远程任务列表 / 导入 / 导出） */
interface ConnectorConfigState {
  type: string;
  endpoint: string;
  authType: string;
  username: string;
  password: string;
  accessKey: string;
  secretKey: string;
}

const config = reactive<ConnectorConfigState>({
  type: '',
  endpoint: '',
  authType: '',
  username: '',
  password: '',
  accessKey: '',
  secretKey: '',
});

/** 组装 ConnectorConfigPostDTO 请求体 */
function toConnectorConfig(): ConnectorConfigPostDTO {
  return {
    endpoint: config.endpoint,
    authType: config.authType || undefined,
    username: config.username || undefined,
    password: config.password || undefined,
    accessKey: config.accessKey || undefined,
    secretKey: config.secretKey || undefined,
  };
}

const taskGridOptions: VxeGridProps<ConnectorTaskInfo> = {
  columns: [
    { type: 'seq', width: 50, title: t('common.seq') },
    { field: 'externalTaskId', title: '远程任务ID', width: 150 },
    { field: 'jobName', title: t('business.jobName'), width: 170 },
    { field: 'jobGroup', title: '分组', width: 110 },
    { field: 'cronExpression', title: 'Cron', width: 150 },
    { field: 'jobType', title: '类型', width: 100 },
    { field: 'executorHandler', title: '执行器Handler', width: 150 },
    { field: 'description', title: '描述', width: 160 },
    { field: 'sourceSystem', title: '来源系统', width: 120 },
  ],
  height: 360,
  pagerConfig: { pageSize: 10, pageSizes: [10, 20, 50] },
  proxyConfig: {
    ajax: {
      query: async () => {
        if (!config.endpoint) {
          return { items: [], total: 0 };
        }
        const items = await listRemoteTasks({ type: config.type || undefined }, toConnectorConfig());
        return { items, total: items.length };
      },
    },
  },
  toolbarConfig: { custom: true, refresh: { code: 'query' }, zoom: true },
};

const [TaskGrid, taskGridApi] = useYDSZVxeGrid({ gridOptions: taskGridOptions });

const [ConnectorFormModal, connectorFormApi] = useYDSZModal({ connectedComponent: ConnectorForm });

onMounted(async () => {
  try {
    connectorTypes.value = await types();
  } catch {
    connectorTypes.value = [];
    // 错误提示由请求拦截器统一处理
  }
});

function handleTest() {
  connectorFormApi.setData({
    record: {
      type: config.type,
      endpoint: config.endpoint,
      authType: config.authType,
      username: config.username,
      password: config.password,
      accessKey: config.accessKey,
      secretKey: config.secretKey,
      types: connectorTypes.value,
    },
  });
  connectorFormApi.open();
}

async function handleImport() {
  if (!config.type || !config.endpoint) {
    ElMessage.warning('请先填写连接器类型与端点');
    return;
  }
  try {
    const res = await importTasks({ type: config.type }, toConnectorConfig());
    ElMessage.success(`导入成功：${res.length} 个任务`);
    taskGridApi.query();
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}

async function handleExport() {
  if (!config.type) {
    ElMessage.warning('请先填写连接器类型');
    return;
  }
  try {
    const res = await exportTasks({ type: config.type });
    ElMessage.success(`导出完成：成功 ${res.success ?? 0}，失败 ${res.failed ?? 0}，跳过 ${res.skipped ?? 0}`);
  } catch {
    // 错误提示由请求拦截器统一处理
  }
}
</script>

<template>
  <Page auto-content-height>
    <div class="mb-2 flex flex-wrap items-center gap-2">
      <span class="text-sm text-gray-500">支持的连接器类型：</span>
      <ElTag v-for="item in connectorTypes" :key="item" type="info">{{ item }}</ElTag>
      <ElTag v-if="connectorTypes.length === 0" type="info">{{ t('common.noData') }}</ElTag>
    </div>
    <ElForm inline class="rounded border border-gray-200 p-2">
      <ElFormItem label="类型">
        <ElInput v-model="config.type" class="w-32" placeholder="连接器类型" />
      </ElFormItem>
      <ElFormItem label="端点">
        <ElInput v-model="config.endpoint" class="w-56" placeholder="连接端点" />
      </ElFormItem>
      <ElFormItem label="认证方式">
        <ElInput v-model="config.authType" class="w-28" placeholder="authType" />
      </ElFormItem>
      <ElFormItem label="用户名">
        <ElInput v-model="config.username" class="w-32" placeholder="用户名" />
      </ElFormItem>
      <ElFormItem label="密码">
        <ElInput v-model="config.password" class="w-32" type="password" show-password placeholder="密码" />
      </ElFormItem>
      <ElFormItem label="AccessKey">
        <ElInput v-model="config.accessKey" class="w-36" placeholder="AccessKey" />
      </ElFormItem>
      <ElFormItem label="SecretKey">
        <ElInput v-model="config.secretKey" class="w-36" type="password" show-password placeholder="SecretKey" />
      </ElFormItem>
    </ElForm>
    <TaskGrid class="mt-4" table-title="远程任务">
      <template #toolbar-tools>
        <ElButton type="primary" @click="handleTest">测试连接</ElButton>
        <ElButton type="warning" plain @click="handleImport">导入任务</ElButton>
        <ElButton type="success" plain @click="handleExport">导出任务</ElButton>
        <ElButton @click="taskGridApi.query()">{{ t('common.search') }}</ElButton>
      </template>
    </TaskGrid>
    <ConnectorFormModal @success="taskGridApi.query()" />
  </Page>
</template>